function ensureEscalationFor(source,type){if(!(source.escalateToSteering===true||source.escalateToSteering==='Yes'))return;const arr=vreg('escalations');let e=arr.find(z=>z.relatedId===source.id);if(!e){e={id:`ESC-${source.id}`,type,relatedId:source.id,title:source.title||source.description||source.id,status:'Open'};arr.push(e)}e.title=source.title||source.description||e.title;e.owner=source.owner||e.owner;e.recommendation=source.recommendation||source.mitigation||e.recommendation;e.committeeDate=source.committeeDate||e.committeeDate;e.reason=source.businessImpact||source.impact||source.background||e.reason;e.status=['Closed','Resolved'].includes(source.status)?'Resolved':(e.status||'Open')}
function editDecision(id){const arr=vreg('decisions'),x=arr.find(d=>d.id===id),d=x||{id:uid('DEC'),category:'Business process',title:'',stream:selectedStream||'Program',owner:'Business Owner',due:'',status:'Open',escalateToSteering:false};const m=modal(x?'Document / edit decision':'Document decision',`<div class="form-grid"><label>ID<input name="id" value="${esc(d.id)}"></label><label>Category<select name="category">${options(['Business process','Scope','Solution design','Data','Integration','Reporting','Control','Customization','Schedule','Governance','Deployment'],d.category||'Business process')}</select></label><label>Stream<select name="stream">${streamOptions(d.stream)}</select></label><label>Owner<input name="owner" value="${esc(d.owner||'Business Owner')}"></label><label class="full">Decision / question<textarea name="title" rows="3">${esc(d.title)}</textarea></label><label class="full">Background / context<textarea name="background" rows="3">${esc(d.background||'')}</textarea></label><label class="full">Options considered<textarea name="options" rows="3">${esc(d.options||'')}</textarea></label><label class="full">Recommendation<textarea name="recommendation" rows="3">${esc(d.recommendation||'')}</textarea></label><label class="full">Decision outcome<textarea name="decisionOutcome" rows="3">${esc(d.decisionOutcome||'')}</textarea></label><label class="full">Decision rationale<textarea name="rationale" rows="3">${esc(d.rationale||'')}</textarea></label><label class="full">Business / project impact<textarea name="businessImpact" rows="3">${esc(d.businessImpact||'')}</textarea></label><label>Linked requirement<input name="linkedRequirement" value="${esc(d.linkedRequirement||'')}"></label><label>Due<input type="date" name="due" value="${esc(d.due||'')}"></label><label>Decision date<input type="date" name="decisionDate" value="${esc(d.decisionDate||'')}"></label><label>Status<select name="status">${options(['Open','Analysis','Recommended','Decided','Closed'],d.status||'Open')}</select></label><label class="check full"><input type="checkbox" name="escalateToSteering" ${d.escalateToSteering===true||d.escalateToSteering==='Yes'?'checked':''}> Escalate to Steering Committee</label><label>Committee date<input type="date" name="committeeDate" value="${esc(d.committeeDate||'')}"></label></div>`);m.querySelector('.modal-save').onclick=()=>{Object.assign(d,vals(m));if(d.status==='Decided'&&!d.decisionDate)d.decisionDate=today();if(!x)arr.push(d);ensureEscalationFor(d,'Decision');mark('registers');m.remove();render()}}
