function bindFlowEditor(){const f=flowFor(selectedFlowId);if(!f)return;$$('.flow-node').forEach(el=>{el.onclick=e=>{e.stopPropagation();if(window._connectFrom){if(window._connectFrom!==el.dataset.node){f.edges.push({from:window._connectFrom,to:el.dataset.node});window._connectFrom=null;markFlow(f);render()}return}selectedNodeId=el.dataset.node;render()};el.ondblclick=e=>{e.stopPropagation();editNode(el.dataset.node)};let st=null;el.onpointerdown=e=>{if(e.button!==0)return;const n=f.nodes.find(x=>x.id===el.dataset.node);st={mx:e.clientX,my:e.clientY,x:n.x,y:n.y,n};el.setPointerCapture(e.pointerId)};el.onpointermove=e=>{if(!st)return;st.n.x=Math.max(0,st.x+e.clientX-st.mx);st.n.y=Math.max(0,st.y+e.clientY-st.my);el.style.left=st.n.x+'px';el.style.top=st.n.y+'px'};el.onpointerup=()=>{if(st){st=null;markFlow(f);render()}}});$('#flowCanvas')?.addEventListener('click',()=>{selectedNodeId=null;render()});$('#addActivity')?.addEventListener('click',()=>{f.nodes.push({id:uid('N'),label:'New activity',system:'',type:'activity',mode:'Manual',x:100,y:100});selectedNodeId=f.nodes.at(-1).id;markFlow(f);render()});$('#addDecisionNode')?.addEventListener('click',()=>{f.nodes.push({id:uid('N'),label:'Decision?',system:'',type:'decision',mode:'Manual',x:180,y:180});selectedNodeId=f.nodes.at(-1).id;markFlow(f);render()});$('#connectNode')?.addEventListener('click',()=>{if(selectedNodeId){window._connectFrom=selectedNodeId;setSync('click target node')}});$('#editNode')?.addEventListener('click',()=>editNode(selectedNodeId));$('#deleteNode')?.addEventListener('click',()=>{if(!selectedNodeId||!confirm('Delete selected step?'))return;f.nodes=f.nodes.filter(n=>n.id!==selectedNodeId);f.edges=f.edges.filter(e=>e.from!==selectedNodeId&&e.to!==selectedNodeId);selectedNodeId=null;markFlow(f);render()})}
